package com.registration.model;
import java.time.LocalDate;
public class Student{private int id;private String fullName,email,phone,gender,course,address;private LocalDate dateOfBirth;public Student(){}public Student(String n,String e,String p,String g,String c,LocalDate d,String a){fullName=n;email=e;phone=p;gender=g;course=c;dateOfBirth=d;address=a;}public int getId(){return id;}public void setId(int v){id=v;}public String getFullName(){return fullName;}public void setFullName(String v){fullName=v;}public String getEmail(){return email;}public void setEmail(String v){email=v;}public String getPhone(){return phone;}public void setPhone(String v){phone=v;}public String getGender(){return gender;}public void setGender(String v){gender=v;}public String getCourse(){return course;}public void setCourse(String v){course=v;}public LocalDate getDateOfBirth(){return dateOfBirth;}public void setDateOfBirth(LocalDate v){dateOfBirth=v;}public String getAddress(){return address;}public void setAddress(String v){address=v;}}